    {
      "cell_type": "code",
      "execution_count": null,
      "metadata": {
        "id": "8PkuXvMPaCuO"
      },
      "outputs": [],
      "source": [
        "_data['日'] = _data['日時'].apply(lambda x : dt.date(x.year,x.month,x.day))\n",
        "_data['時間'] = _data['日時'].apply(lambda x : dt.time(x.hour,x.minute,x.second))\n",
        "_data['降水量(mm)']=_data['降水量(mm)'].mask(_data['降水量(mm)'] == '--', np.nan)\n",
        "_data['降水量(mm)']=_data['降水量(mm)'].mask(_data['降水量(mm)'] == '-- )', np.nan)\n",
        "_data['降水量(mm)']=_data['降水量(mm)'].mask(_data['降水量(mm)'] == '×', np.nan)\n",
        "_data['降水量(mm)']=_data['降水量(mm)'].mask(_data['降水量(mm)'] == '0.0 )', 0.0)\n",
        "_data['降水量(mm)']=_data['降水量(mm)'].astype(float)\n",
        "data = _data[[\"日時\",\"日\",\"時間\",'ポンプ揚水量_総汚水量_ｍ3','降水量(mm)']]\n",
        "data =data.rename(columns={'降水量(mm)':'降雨量1hr累積(mm)'})#降雨量に変更\n"
      ]
    },
