    {
      "cell_type": "markdown",
      "metadata": {
        "id": "RDtwPxdtvBk8"
      },
      "source": [
        "##4-1. 時系列をずらして相互相関を確認する。"
      ]
    },
    {
      "cell_type": "code",
      "execution_count": null,
      "metadata": {
        "id": "oduE9y1c1AS0"
      },
      "outputs": [],
      "source": [
        "_data = data[[\"ポンプ揚水量_総汚水量_ｍ3\",\"降雨量1hr累積(mm)\"]].copy()\n",
        "_data.loc[:,\"降雨量1hr累積(mm)\"]=_data[\"降雨量1hr累積(mm)\"].fillna(0)# NANのままで標準化すると全てNANになってしまうため\n",
        "data_std = stats.zscore(_data)\n",
        "data_std[\"日\"]=data[\"日\"]\n",
        "data_std[\"時間\"]=data[\"時間\"]"
      ]
    },
    {
      "cell_type": "code",
      "execution_count": null,
      "metadata": {
        "id": "E9GS4Xwz2dPI"
      },
      "outputs": [],
      "source": [
        "data_std"
      ]
    },
    {
      "cell_type": "code",
      "execution_count": null,
      "metadata": {
        "id": "Gwo_GG8b2Vr9"
      },
      "outputs": [],
      "source": [
        "time_data_std = pd.pivot_table(data_std,index=data_std[\"時間\"],\n",
        "                           columns=data_std[\"日\"],\n",
        "                           values=\"ポンプ揚水量_総汚水量_ｍ3\")\n",
        "time_data_r_std = pd.pivot_table(data_std,index=data_std[\"時間\"],\n",
        "                           columns=data_std[\"日\"],\n",
        "                           values=\"降雨量1hr累積(mm)\")"
      ]
    },
    {
      "cell_type": "code",
      "execution_count": null,
      "metadata": {
        "id": "y6Et7Oztb_BP"
      },
      "outputs": [],
      "source": [
        "# 相互相関-base\n",
        "a = time_data_std.iloc[:,0]\n",
        "b = time_data_r_std.iloc[:,0]\n",
        "c = time_data_std.columns[0]\n",
        "xc_np_b = np.correlate(a, b, mode='full')\n",
        "xc_np_b /= (np.linalg.norm(a, ord=2) *  np.linalg.norm(b, ord=2))\n",
        "df_xc_b = pd.DataFrame(xc_np_b,columns=[c])"
      ]
    },
    {
      "cell_type": "code",
      "execution_count": null,
      "metadata": {
        "id": "Wk_Wo_5OkvA-"
      },
      "outputs": [],
      "source": [
        "#np.correlateを使った相互相関出力。値はmatolibのxcorrと一致する。\n",
        "df_xc_all = df_xc_b.copy()\n",
        "for i in range(1,len(time_data_std.columns)):\n",
        "  a = time_data_std.iloc[:,i]\n",
        "  b = time_data_r_std.iloc[:,i]\n",
        "  c = time_data_std.columns[i]\n",
        "  xc_np = np.correlate(a, b, mode='full')\n",
        "  xc_np /= (np.linalg.norm(a, ord=2) *  np.linalg.norm(b, ord=2))\n",
        "  df_xc = pd.DataFrame(xc_np,columns=[c])\n",
        "  df_xc_all = pd.concat([df_xc_all,df_xc],axis=1)"
      ]
    },
